/** Results & Experiments workspace (M3-G3).
 *
 * Everything renders from `/api/experiments/coringa_m2/latest`, which serves
 * a recorded run's result.json verbatim — no client-side recomputation, no
 * invented metrics. The charts are the recorded SVGs generated by the M2
 * runner. Where a graph needs interpretation, the page explains axes and
 * what conclusions are (and are not) justified.
 */
import { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "../api/client";
import type { ExperimentSummary } from "../api/types";
import { ErrorNote } from "../components/ui";
import "../styles/experiments.css";

const ha = (value: number) =>
  `${Number(value).toLocaleString("en-GB", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })} ha`;
const pct = (value: number) => `${(Number(value) * 100).toFixed(2)}%`;
const signed = (value: number, digits = 4) =>
  `${value >= 0 ? "+" : ""}${Number(value).toFixed(digits)}`;

function VerdictChip({ verdict }: { verdict: string }) {
  return (
    <span className={`verdict-chip verdict-${verdict}`}>{verdict.replace("_", " ")}</span>
  );
}

function ThresholdExplorer({ experiment }: { experiment: ExperimentSummary }) {
  const [index, setIndex] = useState(experiment.config.indices[0]);
  const [threshold, setThreshold] = useState(experiment.config.primary_threshold);

  const rows = (experiment.primary_threshold_rows[index] ?? [])
    .slice()
    .sort((a, b) => a.threshold - b.threshold);
  const current = rows.find((row) => Math.abs(row.threshold - threshold) < 1e-9);
  const chart = experiment.artifacts.charts.threshold_response;
  const robustness = experiment.temporal_robustness?.[index];
  const robustnessRow = robustness?.available
    ? robustness.rows.find((row) => Math.abs(row.threshold - threshold) < 1e-9)
    : null;

  return (
    <section className="exp-block" aria-labelledby="exp-threshold-title">
      <p className="eyebrow">Threshold sensitivity</p>
      <h2 id="exp-threshold-title">
        How much candidate change depends on the threshold you choose
      </h2>
      <p className="exp-lede">
        A difference map only becomes a "change area" once a threshold declares
        which differences count. The sweep below is the recorded M2 measurement
        of the same study at five thresholds — pick one and the measured areas
        update. Nothing is recomputed in the browser.
      </p>

      <div className="exp-controls">
        <div className="control-group">
          <span className="control-label">Index</span>
          <div className="segmented" role="group" aria-label="Index">
            {experiment.config.indices.map((key) => (
              <button
                key={key}
                type="button"
                className={key === index ? "is-active" : ""}
                aria-pressed={key === index}
                onClick={() => setIndex(key)}
              >
                {key.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
        <div className="control-group">
          <span className="control-label">Threshold |Δ| ≥</span>
          <div className="segmented" role="group" aria-label="Threshold">
            {experiment.config.thresholds.map((value) => (
              <button
                key={value}
                type="button"
                className={Math.abs(value - threshold) < 1e-9 ? "is-active" : ""}
                aria-pressed={Math.abs(value - threshold) < 1e-9}
                onClick={() => setThreshold(value)}
              >
                {Number(value).toFixed(2)}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="exp-two-col">
        <figure className="exp-figure">
          {chart ? (
            <img src={chart} alt={`Threshold response sweep for ${index.toUpperCase()}`} />
          ) : (
            <p className="exp-note">Recorded threshold-response chart unavailable.</p>
          )}
          <figcaption>
            <strong>Reading this chart.</strong> Horizontal axis: the absolute
            threshold applied to the {index.toUpperCase()} difference. Vertical
            axis: fraction of the common-valid AOI classified as candidate
            decrease (teal) or increase (copper) at that threshold. Tighter
            thresholds necessarily shrink the candidate areas — the curves must
            fall monotonically.
          </figcaption>
        </figure>

        <div className="exp-side">
          <h3>
            Measured areas at |Δ{index.toUpperCase()}| ≥ {threshold.toFixed(2)}
          </h3>
          {current ? (
            <table className="exp-table">
              <tbody>
                <tr>
                  <th scope="row">Candidate decrease</th>
                  <td>
                    {ha(current.decrease_area_ha)} ·{" "}
                    {pct(current.decrease_percent_of_common / 100)} of footprint
                  </td>
                </tr>
                <tr>
                  <th scope="row">Unchanged (within threshold)</th>
                  <td>
                    {ha(current.stable_area_ha)} ·{" "}
                    {pct(current.stable_percent_of_common / 100)}
                  </td>
                </tr>
                <tr>
                  <th scope="row">Candidate increase</th>
                  <td>
                    {ha(current.increase_area_ha)} ·{" "}
                    {pct(current.increase_percent_of_common / 100)}
                  </td>
                </tr>
                <tr>
                  <th scope="row">Common-valid footprint</th>
                  <td>{ha(current.valid_area_ha)}</td>
                </tr>
                <tr>
                  <th scope="row">Area conservation</th>
                  <td>{current.area_conservation.ok ? "holds (0 px residual)" : "FAILED"}</td>
                </tr>
              </tbody>
            </table>
          ) : (
            <p className="exp-note">No recorded row for this threshold.</p>
          )}
          {robustnessRow && (
            <p className="exp-note">
              <strong>Observation-selection spread.</strong> Across{" "}
              {robustnessRow.decrease_percent_of_common.count} observation
              selections, the candidate-decrease fraction spans{" "}
              {pct(robustnessRow.decrease_percent_of_common.min / 100)}–
              {pct(robustnessRow.decrease_percent_of_common.max / 100)} at this
              threshold. That spread is part of the honest uncertainty of the
              estimate.
            </p>
          )}
        </div>
      </div>
    </section>
  );
}

function MethodComparison({ experiment }: { experiment: ExperimentSummary }) {
  const [index, setIndex] = useState(experiment.config.indices[0]);
  const rows = experiment.estimators_at_primary
    .filter((item) => item.index === index)
    .sort(
      (a, b) =>
        a.family.localeCompare(b.family) ||
        a.estimator_id.localeCompare(b.estimator_id)
    );
  const chart = experiment.artifacts.charts[`estimator_comparison_${index}`];

  return (
    <section className="exp-block" aria-labelledby="exp-method-title">
      <p className="eyebrow">Method comparison</p>
      <h2 id="exp-method-title">
        The same question, asked of different observation selections
      </h2>
      <p className="exp-lede">
        Each estimator builds its earlier/later surfaces differently — one
        single scene pair, the median of all observations, or the full composite
        with one scene deliberately left out. Differences between the bars are
        therefore <em>observation-selection effects</em>: they measure how
        sensitive the answer is to which satellite passes you trust.
      </p>

      <div className="exp-controls">
        <div className="control-group">
          <span className="control-label">Index</span>
          <div className="segmented" role="group" aria-label="Estimator index">
            {experiment.config.indices.map((key) => (
              <button
                key={key}
                type="button"
                className={key === index ? "is-active" : ""}
                aria-pressed={key === index}
                onClick={() => setIndex(key)}
              >
                {key.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="exp-two-col">
        <figure className="exp-figure">
          {chart ? (
            <img
              src={chart}
              alt={`Estimator comparison chart for ${index.toUpperCase()}`}
            />
          ) : (
            <p className="exp-note">Recorded comparison chart unavailable.</p>
          )}
          <figcaption>
            <strong>Reading this chart.</strong> Each bar is one estimator's
            candidate-change area for {index.toUpperCase()} at the primary
            threshold ±{experiment.config.primary_threshold}. Composite estimators
            (median/mean of {experiment.coverage.periods[0]?.observation_count ?? 3}{" "}
            observations) anchor the middle; single scene pairs and
            leave-one-out variants scatter around them. The spread of the bars —
            not any single bar — is the robustness statement.
          </figcaption>
        </figure>

        <div className="exp-side">
          <h3>Recorded estimators ({rows.length}, {index.toUpperCase()})</h3>
          <div className="exp-table-scroll">
            <table className="exp-table">
              <thead>
                <tr>
                  <th scope="col">Estimator</th>
                  <th scope="col">mean Δ</th>
                  <th scope="col">↓ ha</th>
                  <th scope="col">↑ ha</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((item) => (
                  <tr key={item.estimator_id}>
                    <th scope="row">{item.label}</th>
                    <td>{signed(item.delta_mean)}</td>
                    <td className="value-decrease">
                      {item.decrease_area_ha.toFixed(2)}
                    </td>
                    <td className="value-increase">
                      {item.increase_area_ha.toFixed(2)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </section>
  );
}

function Uncertainty({ experiment }: { experiment: ExperimentSummary }) {
  const [index, setIndex] = useState(experiment.config.indices[0]);
  const bootstrap = experiment.bootstrap?.[index];
  const chart = experiment.artifacts.charts[`bootstrap_${index}`];
  if (!bootstrap) return null;
  return (
    <section className="exp-block" aria-labelledby="exp-uncertainty-title">
      <p className="eyebrow">Measured uncertainty</p>
      <h2 id="exp-uncertainty-title">
        Block bootstrap: how much the number moves under resampling
      </h2>
      <p className="exp-lede">
        The AOI is divided into {bootstrap.block_size_px} px (
        {Number(bootstrap.block_size_m).toFixed(0)} m) blocks and the change
        fractions are recomputed over {bootstrap.iterations_used} block
        resamples (seed {bootstrap.seed}). The interval describes resampling
        variability for <em>this AOI and grid</em> — it is not a population
        confidence interval and not a statement about any other area.
      </p>

      <div className="exp-controls">
        <div className="control-group">
          <span className="control-label">Index</span>
          <div className="segmented" role="group" aria-label="Bootstrap index">
            {experiment.config.indices.map((key) => (
              <button
                key={key}
                type="button"
                className={key === index ? "is-active" : ""}
                aria-pressed={key === index}
                onClick={() => setIndex(key)}
              >
                {key.toUpperCase()}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="exp-two-col">
        <figure className="exp-figure">
          {chart ? (
            <img src={chart} alt={`Block bootstrap intervals for ${index.toUpperCase()}`} />
          ) : (
            <p className="exp-note">Recorded bootstrap chart unavailable.</p>
          )}
          <figcaption>
            <strong>Reading this chart.</strong> For each threshold, the dot is
            the measured fraction and the band is the 2.5th–97.5th percentile
            across block resamples. Wide bands at loose thresholds simply mean
            the candidate areas there are less stable under resampling.
          </figcaption>
        </figure>

        <div className="exp-side">
          <h3>
            Primary threshold ±{experiment.config.primary_threshold} (
            {index.toUpperCase()})
          </h3>
          <table className="exp-table">
            <tbody>
              {(() => {
                const atPrimary = bootstrap.thresholds?.find(
                  (row) =>
                    Math.abs(row.threshold - experiment.config.primary_threshold) < 1e-9
                );
                if (!atPrimary) return null;
                return (
                  <>
                    <tr>
                      <th scope="row">Candidate decrease</th>
                      <td>
                        {pct(atPrimary.decrease_fraction)} · 95% range{" "}
                        {pct(atPrimary.decrease_fraction_ci95.p2_5)}–
                        {pct(atPrimary.decrease_fraction_ci95.p97_5)}
                      </td>
                    </tr>
                    <tr>
                      <th scope="row">Candidate increase</th>
                      <td>
                        {pct(atPrimary.increase_fraction)} · 95% range{" "}
                        {pct(atPrimary.increase_fraction_ci95.p2_5)}–
                        {pct(atPrimary.increase_fraction_ci95.p97_5)}
                      </td>
                    </tr>
                  </>
                );
              })()}
              <tr>
                <th scope="row">Blocks</th>
                <td>
                  {bootstrap.blocks_with_valid_data} with data of{" "}
                  {bootstrap.blocks_total} total
                </td>
              </tr>
              <tr>
                <th scope="row">Resamples</th>
                <td>
                  {bootstrap.iterations_used} of {bootstrap.iterations_requested}
                </td>
              </tr>
            </tbody>
          </table>
          {experiment.cross_pipeline?.available && (
            <p className="exp-note">
              <strong>Cross-pipeline anchor.</strong>{" "}
              {experiment.cross_pipeline.pixels_identical_within_1e_9.toLocaleString("en-GB")}
              /{experiment.cross_pipeline.shared_pixels.toLocaleString("en-GB")}{" "}
              shared NDVI pixels are identical between the M0 and M1 engines
              (within 1e-9), so the two independently implemented pipelines
              agree at the anchor scene.
            </p>
          )}
        </div>
      </div>
    </section>
  );
}

export function ExperimentsPage() {
  const [experiment, setExperiment] = useState<ExperimentSummary | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    api
      .experimentLatest("coringa_m2")
      .then((payload) => {
        if (!cancelled) setExperiment(payload);
      })
      .catch((err: Error) => {
        if (!cancelled) setError(err.message);
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (error) {
    return (
      <main id="main" className="experiments-page">
        <div className="exp-head">
          <p className="eyebrow">Results &amp; experiments</p>
          <h1>No recorded experiment run is available</h1>
          <ErrorNote
            message={`${error}. Recorded runs appear here after \`python scripts/run_experiment.py --config studies/experiments/coringa_m2.yaml\` — this page never invents content to fill the gap.`}
          />
        </div>
      </main>
    );
  }
  if (!experiment) {
    return (
      <main id="main" className="experiments-page">
        <p className="mono-label">Loading recorded experiment run…</p>
      </main>
    );
  }

  const coverage = experiment.coverage;

  return (
    <main id="main" className="experiments-page">
      <header className="exp-head">
        <p className="eyebrow">Results &amp; experiments · Study A</p>
        <h1>Coringa threshold sensitivity, method comparison &amp; measured uncertainty</h1>
        <p className="exp-lede">
          Recorded run <code>{experiment.run_id}</code> · generated{" "}
          {experiment.generated_utc} · fingerprint {String(experiment.fingerprint).slice(0, 16)}…
          . Every number and chart below is read from that run; no supervised
          labels were used anywhere.
        </p>
        <dl className="exp-facts">
          <div>
            <dt>Valid footprint</dt>
            <dd>
              {coverage.aoi_pixels.toLocaleString("en-GB")} AOI px ·{" "}
              {((coverage.pixel_area_m2 * coverage.aoi_pixels) / 10000).toFixed(1)} ha
            </dd>
          </div>
          <div>
            <dt>Common-valid coverage</dt>
            <dd>{pct(coverage.minimum_common_valid_fraction_of_aoi)} of AOI (all indices)</dd>
          </div>
          <div>
            <dt>Observations</dt>
            <dd>
              {coverage.periods
                .map((p) => `${p.period_id} ${p.observation_count}`)
                .join(" · ")}
            </dd>
          </div>
          <div>
            <dt>Composite method</dt>
            <dd>
              M1 {experiment.config.m1_composite_method} ·{" "}
              {experiment.config.indices.map((i) => i.toUpperCase()).join(", ")}
            </dd>
          </div>
        </dl>
      </header>

      <section className="exp-block" aria-labelledby="exp-verdicts-title">
        <p className="eyebrow">Hypothesis verdicts</p>
        <h2 id="exp-verdicts-title">What the run set out to test</h2>
        <ul className="verdict-list">
          {experiment.hypothesis_verdicts.map((verdict) => (
            <li key={verdict.id}>
              <strong>{verdict.id}</strong>
              <VerdictChip verdict={verdict.verdict} />
              <span>{verdict.statement.split(". ").slice(1).join(". ")}</span>
            </li>
          ))}
        </ul>
      </section>

      <ThresholdExplorer experiment={experiment} />
      <MethodComparison experiment={experiment} />
      <Uncertainty experiment={experiment} />

      <section className="exp-block" aria-labelledby="exp-guardrails-title">
        <p className="eyebrow">Scientific interpretation</p>
        <h2 id="exp-guardrails-title">What these results justify — and what they do not</h2>
        <div className="exp-two-col">
          <ul className="exp-guardrails">
            {experiment.guardrails.map((guardrail) => (
              <li key={guardrail}>{guardrail}</li>
            ))}
          </ul>
          <div>
            <h3>Deliberately absent</h3>
            <p className="exp-note">
              No supervised classification accuracy, F1 score or confusion
              matrix appears anywhere in this product: the M2 label-feasibility
              investigation found independent reference labels insufficient, so
              no such numbers exist to show. Candidate-change fractions are
              spectral evidence with stated thresholds, not verified land-cover
              change.
            </p>
            <p className="exp-note">
              NDVI is not proof of mangrove loss or ecological health; MNDWI is
              not direct proof of water discharge; NDBI is not a building
              detector; optical image differencing is not InSAR. Area change
              does not establish environmental causation.
            </p>
          </div>
        </div>
      </section>

      <section className="exp-block" aria-labelledby="exp-exports-title">
        <p className="eyebrow">Export &amp; provenance</p>
        <h2 id="exp-exports-title">Take the recorded numbers with you</h2>
        <ul className="exp-exports">
          <li>
            <a href={experiment.artifacts.result} target="_blank" rel="noopener noreferrer">
              Full result JSON
            </a>
          </li>
          <li>
            <a href={experiment.artifacts.manifest} target="_blank" rel="noopener noreferrer">
              Run manifest (hashes, versions, git commit)
            </a>
          </li>
          <li>
            <a href={experiment.artifacts.estimator_thresholds_csv} target="_blank" rel="noopener noreferrer">
              Estimator × threshold CSV
            </a>
          </li>
          <li>
            <a href={experiment.artifacts.threshold_sensitivity_csv} target="_blank" rel="noopener noreferrer">
              Threshold sensitivity CSV
            </a>
          </li>
          <li>
            <Link to="/methods">Methods, formulas and limitations</Link>
          </li>
        </ul>
        <p className="exp-note">
          Re-running <code>scripts/run_experiment.py</code> with unchanged
          inputs reproduces this run's fingerprint; the API serves the recorded
          run verbatim.
        </p>
      </section>
    </main>
  );
}
